<script setup lang="ts">import {ref,onMounted,watch,computed} from 'vue';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {createRun,cancelRun,retryRun} from '../api/runs';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import {features} from '../constants/enums';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import DatasetSelect from '../components/DatasetSelect.vue';import RunTable from '../components/RunTable.vue';import RunAttempts from '../components/RunAttempts.vue';const lab=useResearch(),auth=useAuth(),data=ref({name:'未见楼宇 · 能耗驱动复核',dataset_id:0,features:Object.keys(features),alphas:[.05,.5,5,25],l1_ratios:[.2,.6,.9],permutation_repeats:20}),message=ref(''),{busy,error,perform}=useTask();const detailRunId=ref(0);const dataset=computed(()=>lab.datasets.find(d=>d.id===data.value.dataset_id)),locked=computed(()=>!!dataset.value?.locked_config),latest=computed(()=>lab.runs.find(r=>r.dataset_id===data.value.dataset_id&&r.status==='completed'));const detailRun=computed(()=>lab.runs.find(r=>r.id===detailRunId.value)||lab.runs[0]);function applyLock(){if(dataset.value?.locked_config)Object.assign(data.value,dataset.value.locked_config);}onMounted(()=>perform(async()=>{await lab.load();data.value.dataset_id=lab.datasets[0]?.id||0;applyLock();}));watch(()=>data.value.dataset_id,applyLock);usePolling(async()=>{if(lab.runs.some(r=>['queued','running'].includes(r.status)))await lab.load();});function submit(){perform(async()=>{const run=await createRun(data.value);message.value=`研究 #${run.id} 已锁定配置并进入分组验证队列。`;detailRunId.value=run.id;await lab.load();applyLock();});}function cancel(id:number){perform(async()=>{await cancelRun(id);message.value=`研究 #${id} 已取消；旧计算即使稍后结束也不会公开封存能耗或驱动解释。`;await lab.load();});}function retry(id:number){perform(async()=>{const run=await retryRun(id);message.value=`研究 #${id} 已沿用最初锁定的方案重新排队（第${run.attempt_count}次尝试），重复点击不会产生新的计算。`;detailRunId.value=id;await lab.load();});}</script><template><PageHeading index="03" title="先在训练楼宇里比较，再揭开封存成绩" text="每一折独立学习均值与尺度；封存楼宇不参与特征或超参数选择。"/><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="model-config-layout"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><h2>{{locked?'复算已锁定方案':'建立分组模型研究'}}</h2><label>研究名称<input v-model="data.name" required minlength="2"></label><DatasetSelect v-model="data.dataset_id" :datasets="lab.datasets"/><p class="lock-message">{{locked?'本数据集配置已锁定，后续研究仅复算同一特征与候选范围。':'首次提交会锁定本数据集的特征与候选范围，再进行封存评估。'}}</p><fieldset :disabled="locked"><legend>特征范围 <small>至少2项</small></legend><div class="feature-options"><label v-for="(label,key) in features" :key="key" class="checkbox"><input v-model="data.features" type="checkbox" :value="key">{{label}}</label></div></fieldset><fieldset :disabled="locked"><legend>α 候选 <small>正则强度</small></legend><div class="inline-options"><label v-for="a in [.05,.5,5,25]" :key="a" class="checkbox"><input v-model="data.alphas" type="checkbox" :value="a">{{a}}</label></div></fieldset><fieldset :disabled="locked"><legend>l1_ratio 候选</legend><div class="inline-options"><label v-for="r in [.2,.6,.9]" :key="r" class="checkbox"><input v-model="data.l1_ratios" type="checkbox" :value="r">{{r}}</label></div></fieldset><fieldset :disabled="locked"><legend>封存置换重复次数</legend><div class="inline-options"><label v-for="p in [10,20,40]" :key="p" class="checkbox"><input v-model="data.permutation_repeats" type="radio" :value="p">{{p}}次</label></div></fieldset><button class="primary" :disabled="busy||data.features.length<2||!data.alphas.length||!data.l1_ratios.length">{{busy?'正在提交…':'锁定并提交分组训练 →'}}</button><p v-if="message" class="success" role="status">{{message}}</p></form><section v-else class="research-form"><h2>联络员阅读工作区</h2><p>可以读取模型比较与驱动解释，并下载已审阅的改造假设。</p></section><aside class="model-notes"><p class="eyebrow">MODEL BASIS / GROUPED VALIDATION</p><h2>一栋楼的90天，<br>不会散进两边。</h2><div class="model-stages"><span>01 <b>先分楼宇</b><small>固定seed97，约25%楼宇封存</small></span><span>02 <b>训练内3折比较</b><small>每折Pipeline独立fit StandardScaler</small></span><span>03 <b>锁定模型后评估</b><small>仅最终模型读取封存目标与置换解释</small></span></div><p>候选按三折平均MAE选优，同分依次选更小α与更小l1_ratio。未收敛的候选保留记录，不进入选优。</p><p>排队或运行中的研究可随时取消；失败或取消后可沿用锁定方案重试，每次尝试的进度与原因都留痕。</p></aside></div><section v-if="latest" class="candidate-comparison"><div class="section-heading"><h2>训练楼宇内的候选比较</h2><span>{{latest.name}}</span></div><div class="table-wrap"><table><thead><tr><th>α</th><th>l1_ratio</th><th>折1 MAE</th><th>折2 MAE</th><th>折3 MAE</th><th>平均MAE</th><th>收敛 / 选择</th></tr></thead><tbody><tr v-for="c in latest.result.candidates" :key="c.alpha+'-'+c.l1_ratio" :class="{chosen:c.alpha===latest.result.best?.alpha&&c.l1_ratio===latest.result.best?.l1_ratio}"><td>{{c.alpha}}</td><td>{{c.l1_ratio}}</td><td v-for="(score,i) in c.fold_maes" :key="i">{{score.toFixed(3)}}</td><td>{{c.mean_mae.toFixed(3)}}</td><td>{{!c.converged?'未收敛':c.alpha===latest.result.best?.alpha&&c.l1_ratio===latest.result.best?.l1_ratio?'已选定':'收敛'}}</td></tr></tbody></table></div></section><section class="run-directory"><div class="section-heading"><h2>研究运行记录</h2><span>运行中自动刷新，可取消与重试</span></div><RunTable :runs="lab.runs" :busy="busy" @cancel="cancel" @retry="retry"/></section><section v-if="detailRun" class="attempt-section"><div class="section-heading"><h2>每次尝试的进度与原因</h2><select v-model="detailRunId"><option v-for="r in lab.runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></div><RunAttempts :attempts="detailRun.attempts"/></section></template>
